import{_ as i,a0 as o,w as d,s as r,I as n,x as s,a1 as t,A as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 pdftk 為 PDF 文檔創建書籤 | LCTT x X-CMD","titleTemplate":false,"description":"使用 pdftk 為 PDF 文檔創建書籤 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 pdftk 為 PDF 文檔創建書籤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 pdftk 為 PDF 文檔創建書籤 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20220105 Create bookmarks for your PDF with pdftk","title":"使用 pdftk 為 PDF 文檔創建書籤","tag":"202307","desc":""},"relativePath":"202307/20220105 Create bookmarks for your PDF with pdftk.md","filePath":"[post].md"}'),f={name:"202307/20220105 Create bookmarks for your PDF with pdftk.md"};function u(k,a,m,b,g,P){const p=o("Link");return d(),r("div",null,[a[42]||(a[42]=n("h1",{id:"使用-pdftk-為-pdf-文檔創建書籤",tabindex:"-1"},[s("使用 pdftk 為 PDF 文檔創建書籤 "),n("a",{class:"header-anchor",href:"#使用-pdftk-為-pdf-文檔創建書籤","aria-label":"Permalink to “使用 pdftk 為 PDF 文檔創建書籤”"},"​")],-1)),a[43]||(a[43]=n("blockquote",null,[n("p",null,"充分利用現有的技術，提供書籤以幫助用户。")],-1)),a[44]||(a[44]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202307/06/185044ioz6nw1jqkqnhx66.jpg",alt:""})],-1)),n("p",null,[a[1]||(a[1]=s("在 ",-1)),t(p,{href:"https://opensource.com/article/21/12/edit-pdf-linux-pdftk"},{default:e(()=>[...a[0]||(a[0]=[s("介紹 pdftk-java",-1)])]),_:1}),a[2]||(a[2]=s(" 中, 我展示瞭如何在腳本中使用 ",-1)),a[3]||(a[3]=n("code",null,"pdftk-java",-1)),a[4]||(a[4]=s(" 來快速修改 PDF 文件。",-1))]),a[45]||(a[45]=l('<p>但是，<code>pdftk-java</code> 最有用的場景是處理那種動輒幾百頁的沒有目錄的大 PDF 文件。這裏所謂的目錄不是指文檔前面供打印的目錄，而是指顯示在 PDF 閲讀器側邊欄裏的目錄，它在 PDF 格式中的正式叫法是“<ruby>書籤<rt>bookmarks</rt></ruby>”。</p><p><img src="https://opensource.com/sites/default/files/uploads/pdtfk_update.jpeg" alt="Screenshot of a sidebar table of contents next to a PDF" title="table of contents"></p><p>如果沒有書籤，就只能通過上下滾動或全局搜索文本來定位想要的章節，這非常麻煩。</p><p>PDF 文件的另一個惱人的小問題是缺乏元數據，比如標題和作者。如果你打開過一個標題欄上顯示類似 “Microsoft Word - 04_Classics_Revisited.docx” 的 PDF 文件，你就能體會那種感覺了。</p><p><code>pdftk-java</code> 讓我能夠創建自己的書籤，我再也不面對這些問題了。</p><h3 id="在-linux-上安裝-pdftk-java" tabindex="-1">在 Linux 上安裝 pdftk-java <a class="header-anchor" href="#在-linux-上安裝-pdftk-java" aria-label="Permalink to “在 Linux 上安裝 pdftk-java”">​</a></h3><p>正如 <code>pdftk-java</code> 的名稱所示的，它是用 Java 編寫的。它能夠在所有主流操作系統上運行，只要你安裝了 Java。</p>',7)),n("p",null,[a[6]||(a[6]=s("Linux 和 macOS 用户可以從 ",-1)),t(p,{href:"https://adoptopenjdk.net/releases.html"},{default:e(()=>[...a[5]||(a[5]=[s("AdoptOpenJDK.net",-1)])]),_:1}),a[7]||(a[7]=s(" 安裝 Java（LCTT 譯註：原文為 Linux，應為筆誤）。",-1))]),n("p",null,[a[9]||(a[9]=s("Windows 用户可以安裝 ",-1)),t(p,{href:"https://developers.redhat.com/products/openjdk/download"},{default:e(()=>[...a[8]||(a[8]=[s("Red Hat's Windows build of OpenJDK",-1)])]),_:1}),a[10]||(a[10]=s("。",-1))]),a[46]||(a[46]=n("p",null,"在 Linux 上安裝 pdftk-java：",-1)),n("ol",null,[n("li",null,[a[13]||(a[13]=s("從 Gitlab 倉庫下載 ",-1)),t(p,{href:"https://gitlab.com/pdftk-java/pdftk/-/jobs/1527259628/artifacts/raw/build/libs/pdftk-all.jar"},{default:e(()=>[...a[11]||(a[11]=[s("pdftk-all.jar release",-1)])]),_:1}),a[14]||(a[14]=s("，保存至 ",-1)),a[15]||(a[15]=n("code",null,"~/.local/bin/",-1)),a[16]||(a[16]=s(" 或 ",-1)),t(p,{href:"https://opensource.com/article/17/6/set-path-linux"},{default:e(()=>[...a[12]||(a[12]=[s("其它路徑",-1)])]),_:1}),a[17]||(a[17]=s(" 下.",-1))]),a[18]||(a[18]=n("li",null,[s("用文本編輯器打開 "),n("code",null,"~/.bashrc"),s("，添加 "),n("code",null,"alias pdftk='java -jar $HOME/.local/bin/pdftk-all.jar'")],-1)),a[19]||(a[19]=n("li",null,[s("運行 "),n("code",null,"source ~/.bashrc"),s(" 使新的 Bash 設置生效。")],-1))]),a[47]||(a[47]=l(`<h3 id="數據轉儲" tabindex="-1">數據轉儲 <a class="header-anchor" href="#數據轉儲" aria-label="Permalink to “數據轉儲”">​</a></h3><p>修改元數據的第一步是抽取 PDF 當前的數據文件。</p><p>現在的數據文件可能並沒包含多少內容，但這也是一個不錯的開端。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pdftk mybigfile.pdf \\</span></span>
<span class="line"><span>  data_dump \\</span></span>
<span class="line"><span>  output bookmarks.txt</span></span></code></pre></div><p>生成的 <code>bookmarks.txt</code> 文件中包含了輸入 PDF 文件 <code>mybigfile.pdf</code> 的所有元數據和一大堆無用數據。</p><h3 id="編輯元數據" tabindex="-1">編輯元數據 <a class="header-anchor" href="#編輯元數據" aria-label="Permalink to “編輯元數據”">​</a></h3>`,6)),n("p",null,[a[22]||(a[22]=s("用文本編輯器（比如 ",-1)),t(p,{href:"https://opensource.com/article/20/12/atom"},{default:e(()=>[...a[20]||(a[20]=[s("Atom",-1)])]),_:1}),a[23]||(a[23]=s(" 或 ",-1)),t(p,{href:"https://opensource.com/article/20/12/gedit"},{default:e(()=>[...a[21]||(a[21]=[s("Gedit",-1)])]),_:1}),a[24]||(a[24]=s("）打開 ",-1)),a[25]||(a[25]=n("code",null,"bookmarks.txt",-1)),a[26]||(a[26]=s(" 以編輯 PDF 元數據。",-1))]),a[48]||(a[48]=l(`<p>元數據的格式和數據項直觀易懂：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>InfoBegin</span></span>
<span class="line"><span>InfoKey: Creator</span></span>
<span class="line"><span>InfoValue: Word</span></span>
<span class="line"><span>InfoBegin</span></span>
<span class="line"><span>InfoKey: ModDate</span></span>
<span class="line"><span>InfoValue: D:20151221203353Z00&amp;amp;apos;00&amp;amp;apos;</span></span>
<span class="line"><span>InfoBegin</span></span>
<span class="line"><span>InfoKey: CreationDate</span></span>
<span class="line"><span>InfoValue: D:20151221203353Z00&amp;amp;apos;00&amp;amp;apos;</span></span>
<span class="line"><span>InfoBegin</span></span>
<span class="line"><span>InfoKey: Producer</span></span>
<span class="line"><span>InfoValue: Mac OS X 10.10.4 Quartz PDFContext</span></span>
<span class="line"><span>InfoBegin</span></span>
<span class="line"><span>InfoKey: Title</span></span>
<span class="line"><span>InfoValue: Microsoft Word - 04_UA_Classics_Revisited.docx</span></span>
<span class="line"><span>PdfID0: f049e63eaf3b4061ddad16b455ca780f</span></span>
<span class="line"><span>PdfID1: f049e63eaf3b4061ddad16b455ca780f</span></span>
<span class="line"><span>NumberOfPages: 42</span></span>
<span class="line"><span>PageMediaBegin</span></span>
<span class="line"><span>PageMediaNumber: 1</span></span>
<span class="line"><span>PageMediaRotation: 0</span></span>
<span class="line"><span>PageMediaRect: 0 0 612 792</span></span>
<span class="line"><span>PageMediaDimensions: 612 792</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>你可以將 <code>InfoValue</code> 的值修改為對當前 PDF 有意義的內容。比如可以將 <code>Creator</code> 字段從 <code>Word</code> 修改為實際的作者或出版社名稱。比起使用導出程序自動生成的標題，使用書籍的實際標題會更好。</p><p>你也可以做一些清理工作。在 <code>NumberOfPages</code> 之後的行都不是必需的，可以刪除這些行的內容。</p><h3 id="添加書籤" tabindex="-1">添加書籤 <a class="header-anchor" href="#添加書籤" aria-label="Permalink to “添加書籤”">​</a></h3><p>PDF 書籤的格式如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>BookmarkBegin</span></span>
<span class="line"><span>BookmarkTitle: My first bookmark</span></span>
<span class="line"><span>BookmarkLevel: 1</span></span>
<span class="line"><span>BookmarkPageNumber: 2</span></span></code></pre></div><ul><li><code>BookmarkBegin</code> 表示這是一個書籤。</li><li><code>BookmarkTitle</code> 書籤在 PDF 閲讀器中顯示的文本。</li><li><code>BookmarkLevel</code> 書籤層級。如果書籤層級為 2，它將出現在上一個書籤的小三角下。如果設置為 3，它會顯示在上一個 2 級書籤的小三角下。這讓你能為章以及其中的節設置書籤。</li><li><code>BookmarkPageNumber</code> 點擊書籤時轉到的頁碼。</li></ul><p>為你需要的章節創建書籤，然後保存文件。</p><h3 id="更新書籤信息" tabindex="-1">更新書籤信息 <a class="header-anchor" href="#更新書籤信息" aria-label="Permalink to “更新書籤信息”">​</a></h3><p>現在已經準備好了元數據和書籤，你可以將它們導入到 PDF 文件中。實際上是將這些信息導入到一個新的 PDF 文件中，它的內容與原 PDF 文件相同：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pdftk mybigfile.pdf \\</span></span>
<span class="line"><span>  update_info bookmarks.txt \\</span></span>
<span class="line"><span>  output mynewfile.pdf</span></span></code></pre></div><p>生成的 <code>mynewfile.pdf</code> 包含了你設置的全部元數據和書籤。</p><h3 id="體現專業性" tabindex="-1">體現專業性 <a class="header-anchor" href="#體現專業性" aria-label="Permalink to “體現專業性”">​</a></h3><p>PDF 文件中是否包含定製化的元數據和書籤可能並不會影響銷售。</p><p>但是，關注元數據可以向用户表明你重視質量保證。增加書籤可以為用户提供便利，同時亦是充分利用現有技術。</p><p>使用 <code>pdftk-java</code> 來簡化這個過程，用户會感激不盡。</p><p><em>（題圖：MJ/f8869a66-562d-4ee4-9f2d-1949944d6a9c）</em></p><hr>`,19)),n("p",null,[a[28]||(a[28]=s("via: ",-1)),t(p,{href:"https://opensource.com/article/22/1/pdf-metadata-pdftk"},{default:e(()=>[...a[27]||(a[27]=[s("https://opensource.com/article/22/1/pdf-metadata-pdftk",-1)])]),_:1})]),n("p",null,[a[33]||(a[33]=s("作者：",-1)),t(p,{href:"https://opensource.com/users/seth"},{default:e(()=>[...a[29]||(a[29]=[s("Seth Kenlon",-1)])]),_:1}),a[34]||(a[34]=s(" 選題：",-1)),t(p,{href:"https://github.com/lujun9972"},{default:e(()=>[...a[30]||(a[30]=[s("lujun9972",-1)])]),_:1}),a[35]||(a[35]=s(" 譯者：",-1)),t(p,{href:"https://github.com/toknow-gh"},{default:e(()=>[...a[31]||(a[31]=[s("toknow-gh",-1)])]),_:1}),a[36]||(a[36]=s(" 校對：",-1)),t(p,{href:"https://github.com/wxy"},{default:e(()=>[...a[32]||(a[32]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[39]||(a[39]=s("本文由 ",-1)),t(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[37]||(a[37]=[s("LCTT",-1)])]),_:1}),a[40]||(a[40]=s(" 原創編譯，",-1)),t(p,{href:"https://linux.cn/"},{default:e(()=>[...a[38]||(a[38]=[s("Linux中國",-1)])]),_:1}),a[41]||(a[41]=s(" 榮譽推出",-1))])])}const T=i(f,[["render",u]]);export{x as __pageData,T as default};
